using U=uint32_t;
std::string fixtures,output;int rank_id;
template<class T>std::vector<T>readfile(std::string p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||size_t(f.tellg())!=n*sizeof(T)){fprintf(stderr,"fileextent%s expected%zu\n",p.c_str(),n*sizeof(T));exit(3);}f.seekg(0);std::vector<T>x(n);f.read((char*)x.data(),n*sizeof(T));if(!f)exit(3);return x;}
std::string file(std::string name,int r=-1){return fixtures+"/rank"+std::to_string(r<0?rank_id:r)+"_"+name+".bin";}
U floatbits(float x){U y;memcpy(&y,&x,4);return y;}float asfloat(U x){float y;memcpy(&y,&x,4);return y;}
struct Buf{std::string name;size_t n;bool integer;U*base;std::vector<U>initial;Buf(const char*nm,size_t count,const char*input=nullptr,bool ints=false):name(nm),n(count),integer(ints),initial(n+256,ints?0x13579bdf:floatbits(4096.25f)){std::fill(initial.begin()+128,initial.end()-128,0);if(input){auto x=readfile<U>(file(input),n);std::copy(x.begin(),x.end(),initial.begin()+128);}C(cudaMalloc(&base,(n+256)*4));C(cudaMemcpy(base,initial.data(),(n+256)*4,cudaMemcpyHostToDevice));}~Buf(){C(cudaFree(base));}float*f(){return(float*)(base+128);}int*i(){return(int*)(base+128);}std::vector<U>raw(){std::vector<U>x(n+256);C(cudaMemcpy(x.data(),base,x.size()*4,cudaMemcpyDeviceToHost));return x;}std::vector<float>values(){std::vector<float>x(n);C(cudaMemcpy(x.data(),f(),n*4,cudaMemcpyDeviceToHost));return x;}};
void append(std::vector<double>&to,const std::vector<U>&raw,bool integer){for(U v:raw){double d=integer?double(int32_t(v)):double(asfloat(v));if(!std::isfinite(d)){fprintf(stderr,"nonfinitecapture\n");exit(4);}to.push_back(d);}}
void guards(Buf&b,const std::vector<U>&x){if(!std::equal(x.begin(),x.begin()+128,b.initial.begin())||!std::equal(x.end()-128,x.end(),b.initial.end()-128)){fprintf(stderr,"guard%s\n",b.name.c_str());exit(4);}}
double maxerr=0,maxratio=0;
void check(const std::vector<float>&actual,const std::string&field,int stage,int ref_rank=-1,const std::vector<int>*map=nullptr,size_t live=0){int r=ref_rank<0?rank_id:ref_rank;auto ref=readfile<double>(file("stage"+std::to_string(stage)+"_"+field+"_reference_f64",r),294336);auto bound=readfile<double>(file("stage"+std::to_string(stage)+"_"+field+"_bound_f64",r),294336);size_t n=map?live:actual.size();for(size_t j=0;j<n;j++){size_t idx=map?(*map)[j]:j;double err=std::abs(double(actual[j])-ref[idx]);maxerr=std::max(maxerr,err);maxratio=std::max(maxratio,err/bound[idx]);if(!std::isfinite(actual[j])||err>bound[idx]){fprintf(stderr,"oracle rank%d stage%d %s index%zu err%.17g bound%.17g\n",rank_id,stage,field.c_str(),j,err,bound[idx]);exit(5);}}}
void dump(const std::vector<float>&v,const char*field,int stage){std::string p=output+"/rank"+std::to_string(rank_id)+"_stage"+std::to_string(stage)+"_"+field+".bin";std::ofstream f(p,std::ios::binary);f.write((char*)v.data(),v.size()*4);if(!f)exit(6);}
