for(int trial=0;trial<=5;trial++){maxerr=maxratio=0;Buf Q("Q",294336,"initial_Q"),rhs("rhs",294336,"initial_rhs"),res("res",294336,"initial_res"),tmp("tmp",294336),part("part",12768),D("D",36864,"DrDsDt"),L("L",9408,"LIFT"),G("G",6132,"vgeo"),S("S",400624,"surfinfo"),M("map",12768,"parmapOUT",true);std::vector<Buf*>all{&Q,&rhs,&res,&tmp,&part,&D,&L,&G,&S,&M};std::vector<double>prefix,values;
