auto tq=texture<float>(Q),tp=texture<float>(part),td=texture<float4>(D),tl=texture<float4>(L),tg=texture<float>(G),ts=texture<float>(S);C(cudaMemcpyToSymbol(t_Q,&tq,sizeof(tq)));C(cudaMemcpyToSymbol(t_partQ,&tp,sizeof(tp)));C(cudaMemcpyToSymbol(t_DrDsDt,&td,sizeof(td)));C(cudaMemcpyToSymbol(t_LIFT,&tl,sizeof(tl)));C(cudaMemcpyToSymbol(t_vgeo,&tg,sizeof(tg)));C(cudaMemcpyToSymbol(t_surfinfo,&ts,sizeof(ts)));std::vector<float>send(12768),recv(12768);C(cudaDeviceSynchronize());study_mpi_barrier();double start=study_mpi_time();study_mpi_barrier();
for(int stage=1;stage<=5;stage++){partial_get_kernel3d<<<50,256>>>(12768,M.i(),tmp.f());C(cudaMemcpy(send.data(),tmp.f(),12768*4,cudaMemcpyDeviceToHost));study_mpi_start(send.data(),recv.data(),12768);if(!trial)dump(send,"gathered",stage);MaxwellsGPU_VOL_Kernel3D<<<511,84>>>(rhs.f());if(!trial){auto v=rhs.values();check(v,"volume_rhs",stage);dump(v,"volume_rhs",stage);}study_mpi_finish();C(cudaMemcpy(part.f(),recv.data(),12768*4,cudaMemcpyHostToDevice));if(!trial)dump(recv,"received",stage);MaxwellsGPU_SURF_Kernel3D<<<511,112>>>(rhs.f());if(!trial){auto v=rhs.values();check(v,"surface_rhs",stage);dump(v,"surface_rhs",stage);}MaxwellsGPU_RK_Kernel3D<<<1150,256>>>(294336,res.f(),rhs.f(),Q.f(),float(a[stage-1]),float(b[stage-1]),.0005f);if(!trial){auto q=Q.values(),r=res.values();check(q,"Q",stage);check(r,"res",stage);dump(q,"Q",stage);dump(r,"res",stage);}}
C(cudaDeviceSynchronize());double seconds=study_mpi_time()-start;study_mpi_barrier();C(cudaGetLastError());check(Q.values(),"Q",5);check(rhs.values(),"surface_rhs",5);check(res.values(),"res",5);check(send,"Q",4,rank_id,&map,12768);check(recv,"Q",4,1-rank_id,&peermap,12768);
for(auto*p:all){auto x=p->raw();guards(*p,x);if(p==&D||p==&L||p==&G||p==&S||p==&M){if(x!=p->initial)exit(4);}if(p==&tmp)for(size_t j=128+12768;j<x.size()-128;j++)if(x[j]!=0)exit(4);append(values,x,p->integer);}
